//! Generated files and writing them to disk.

use std::collections::HashSet;
use std::io;
use std::path::{Path, PathBuf};

/// First line of every file the generator owns. Files carrying it may be
/// overwritten or removed; anything else is left alone.
pub const MARKER: &str = "Generated by LVGLab";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum WritePolicy {
    /// Always regenerated.
    Overwrite,
    /// Created once; the user owns it afterwards.
    KeepExisting,
}

#[derive(Clone, Debug)]
pub struct GeneratedFile {
    /// Relative path with `/` separators.
    pub path: String,
    pub contents: Vec<u8>,
    pub policy: WritePolicy,
}

impl GeneratedFile {
    pub fn text(path: impl Into<String>, contents: String, policy: WritePolicy) -> Self {
        Self { path: path.into(), contents: contents.into_bytes(), policy }
    }

    pub fn contents_str(&self) -> &str {
        std::str::from_utf8(&self.contents).unwrap_or_default()
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct WriteSummary {
    pub written: usize,
    pub unchanged: usize,
    pub kept: usize,
    pub removed: usize,
}

/// Writes all files below `root`. Stale generated files below the given
/// `managed_dirs` (relative to `root`) are removed.
pub fn write_all(root: &Path, files: &[GeneratedFile], managed_dirs: &[&str]) -> io::Result<WriteSummary> {
    let mut summary = WriteSummary::default();
    let mut produced = HashSet::new();
    for file in files {
        let path = root.join(&file.path);
        produced.insert(normalize(&path));
        if path.exists() {
            if file.policy == WritePolicy::KeepExisting {
                summary.kept += 1;
                continue;
            }
            if std::fs::read(&path)? == file.contents {
                summary.unchanged += 1;
                continue;
            }
        }
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir)?;
        }
        std::fs::write(&path, &file.contents)?;
        summary.written += 1;
    }
    for dir in managed_dirs {
        summary.removed += prune(&root.join(dir), &produced)?;
    }
    Ok(summary)
}

fn normalize(path: &Path) -> PathBuf {
    path.components().collect()
}

fn prune(dir: &Path, keep: &HashSet<PathBuf>) -> io::Result<usize> {
    let Ok(entries) = std::fs::read_dir(dir) else { return Ok(0) };
    let mut removed = 0;
    for entry in entries {
        let path = entry?.path();
        if path.is_dir() {
            removed += prune(&path, keep)?;
        } else if !keep.contains(&normalize(&path)) && is_generated(&path) {
            std::fs::remove_file(&path)?;
            removed += 1;
        }
    }
    Ok(removed)
}

fn is_generated(path: &Path) -> bool {
    use std::io::BufRead;
    let Ok(file) = std::fs::File::open(path) else { return false };
    let mut first = String::new();
    io::BufReader::new(file).read_line(&mut first).is_ok() && first.contains(MARKER)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn writes_keeps_and_prunes() {
        let root = std::env::temp_dir().join(format!("lvglab-codegen-out-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let generated =
            |path: &str, text: &str, policy| GeneratedFile::text(path, format!("// {MARKER}\n{text}"), policy);
        let files = vec![
            generated("ui/a.c", "a", WritePolicy::Overwrite),
            generated("ui/stale.c", "s", WritePolicy::Overwrite),
            generated("ui/user.c", "u", WritePolicy::KeepExisting),
        ];
        assert_eq!(write_all(&root, &files, &["ui"]).unwrap().written, 3);
        std::fs::write(root.join("ui/own.c"), "mine").unwrap();

        let files = vec![
            generated("ui/a.c", "a", WritePolicy::Overwrite),
            generated("ui/user.c", "x", WritePolicy::KeepExisting),
        ];
        let summary = write_all(&root, &files, &["ui"]).unwrap();
        assert_eq!(summary, WriteSummary { written: 0, unchanged: 1, kept: 1, removed: 1 });
        assert!(!root.join("ui/stale.c").exists());
        assert!(root.join("ui/own.c").exists());
        assert!(std::fs::read_to_string(root.join("ui/user.c")).unwrap().ends_with('u'));
        std::fs::remove_dir_all(root).ok();
    }
}
